"""Verify artifacts generated by the real server projection/shared production renderer."""
import hashlib,json,re
from pathlib import Path
import pdfplumber
from pypdf import PdfReader
ROOT=Path(__file__).resolve().parents[1]
folder=ROOT/'output/pdf/document-review-v1'
manifest=json.loads((folder/'manifest.json').read_text())
candidate=json.loads((ROOT/'src/lib/productionV2/proposedPackages/originals-v1.json').read_text())
count=0
def check(ok,label):
 global count
 assert ok,label
 count+=1
 print('PASS '+label)
def norm(text):return re.sub(r'\s+',' ',text).strip()
def images(page):return sum(v.get_object().get('/Subtype')=='/Image' for v in page['/Resources'].get_object().get('/XObject',{}).values())
check(manifest['status']=='PROPOSED_NOT_APPROVED' and not manifest['installable'],'not approved or installable')
check([p['version'] for p in json.loads((ROOT/'src/lib/productionV2/finalPackages.json').read_text())]==['OWNER_FINAL_UPLOADED_20261025_V1'],'only exact owner final package installed; historical proposals excluded')
p=manifest['projection'];texts={}
for kind,info in manifest['pdfs'].items():
 path=folder/info['path'];reader=PdfReader(path);text=norm(' '.join(page.extract_text() for page in reader.pages));texts[kind]=text
 check(hashlib.sha256(path.read_bytes()).hexdigest()==info['sha256'],kind+' hash')
 check(len(reader.pages)==info['pages'],kind+' pages')
 check(all('BORRADOR — NO VÁLIDO PARA FIRMA' in norm(page.extract_text()) for page in reader.pages),kind+' watermark on every page')
 check(all(images(page)==0 for page in reader.pages) if kind=='PAGARE' else all(images(page)>0 for page in reader.pages),kind+' branding')
 check(all(v in text for v in [p['customer']['fullName'],'LOOP GESTIÓN INTEGRAL S.R.L.','30-71962686-2','Caracas 1101']),kind+' selectable identity')
 check(not re.search(r'\bCH-\d',text) and 'Sin numeración definitiva' in text and '30-71829384-9' not in text,kind+' no final number or obsolete tax ID')
 for block in candidate['documents'][kind]['blocks']:
  if block['type'] in ['paragraph','heading'] and '{{' not in block['text']:
   expected=block['text'].replace('[LUGAR DE PAGO PENDIENTE DE VALIDACIÓN]','[PENDIENTE DE VALIDACIÓN]').replace('[COMPETENCIA DEL PAGARÉ PENDIENTE DE VALIDACIÓN]','[PENDIENTE DE VALIDACIÓN]')
   check(norm(expected) in text,kind+' complete original clause '+block['id'])
 with pdfplumber.open(path) as doc:
  check(all(39<=w['x0']<w['x1']<=558 and 10<=w['top']<w['bottom']<=824 for page in doc.pages for w in page.extract_words()),kind+' page bounds')
def money(n):return '$ '+format(n,',').replace(',','.')+',00'
e=p['economics'];check(e['capital']+e['service']==e['total'] and sum(x['amount'] for x in p['schedule'])==e['total'],'persisted economics reconcile')
check(money(e['total']) in texts['MANDATE'] and money(e['total']) in texts['PAGARE'],'same saved total mandate and note')
check(money(e['capital']) in texts['MANDATE'] and money(e['service']) in texts['MANDATE'],'saved capital and gross services')
for row in p['schedule']:check(norm(f"{row['installmentNumber']} {money(row['amount'])} {row['dueDate']}") in texts['MANDATE'],'saved installment '+str(row['installmentNumber']))
check('tribunales competentes correspondientes al domicilio del cliente' in texts['MANDATE'],'mandate jurisdiction unchanged')
check('Tribunales Ordinarios de la ciudad de [PENDIENTE DE VALIDACIÓN]' in texts['PAGARE'],'note jurisdiction independently pending')
check('capitalizará mensualmente' in texts['PAGARE'] and '[PENDIENTE DE VALIDACIÓN]%' in texts['PAGARE'],'capitalization preserved without invented rate')
check('Costo Financiero Total (CFT) [PENDIENTE DE VALIDACIÓN]' in texts['MANDATE'],'allocation not fabricated')
check('READ_ONLY_PREVIEW_THREE_DOCUMENTS_REPRODUCIBLE_NO_NUMBER_NO_WRITES' in manifest['checks'],'independent server reads produced identical bytes without writes')
print(json.dumps({'status':'PASS','checks':count,'productionWrites':0}))
